#include <stdio.h>
#include <stdint.h>
#include <string.h>

static void show(float f) {
    uint32_t bits;
    memcpy(&bits, &f, sizeof bits);
    unsigned s = (bits >> 31) & 1u;
    unsigned e = (bits >> 23) & 0xFFu;
    unsigned m = bits & 0x7FFFFFu;
    const char *kind = "normalized";
    int eff;
    if (e == 0u && m == 0u)        kind = "zero";
    else if (e == 0u)              kind = "denormal";
    else if (e == 0xFFu && m == 0u) kind = "infinity";
    else if (e == 0xFFu)           kind = "NaN";

    /* 有效阶码：规格化是 E-127；非规格化固定为 -126（偏置减一）；全 1 无意义 */
    if (e == 0u)            eff = -126;
    else if (e == 0xFFu)    eff = 0;
    else                    eff = (int)e - 127;

    printf("  bits=0x%08X  S=%u  E=%3u  e_eff=%5d  M=0x%06X  %s\n",
           bits, s, e, eff, m, kind);
}

int main(void) {
    uint32_t small_normal = 0x00800000u;   /* E=1, M=0      */
    uint32_t small_denorm = 0x00000001u;   /* E=0, M=1      */
    uint32_t large_denorm = 0x007FFFFFu;   /* E=0, M=all 1s */
    float f1, f2, f3;
    memcpy(&f1, &small_normal, 4);
    memcpy(&f2, &small_denorm, 4);
    memcpy(&f3, &large_denorm, 4);

    printf("=== IEEE 754 single precision ===\n");
    printf("  layout: bit31=S, bit30..23=E (bias 127), bit22..0=M (hidden leading 1)\n");
    printf("  value = (-1)^S * 1.M * 2^(E-127)\n\n");

    printf("  --- ordinary values ---\n");
    show(1.0f);
    show(-1.0f);
    show(0.5f);
    show(2.0f);
    show(3.5f);
    show(0.1f);

    printf("\n  --- boundaries ---\n");
    show(f1);  printf("        <- smallest positive NORMAL   (exponent field 1)\n");
    show(f2);  printf("        <- smallest positive DENORMAL (exponent field 0)\n");
    show(f3);  printf("        <- largest DENORMAL: it glues onto the smallest normal\n");

    printf("\n  --- why 0.1 is not exact ---\n");
    printf("  0.1 stored as float  = %.20f\n", (double)0.1f);
    printf("  0.1 stored as double = %.20f\n", 0.1);
    printf("  0.1 has an INFINITE binary expansion, so the last bit must be rounded\n");

    printf("\n  --- bias arithmetic ---\n");
    printf("  1.0f -> E=127 -> stored 127 -> e = 127-127 = 0 -> 1.0 * 2^0\n");
    printf("  0.5f -> E=126 -> stored 126 -> e = 126-127 = -1 -> 1.0 * 2^-1\n");
    printf("  denormal exponent is FIXED at -126 (bias minus one), which is why it glues on\n");
    return 0;
}
